<?php
namespace Delnavazan\Platform\Admin\Controller;

use Delnavazan\Platform\Core\Application\Finance\OperationalCashLedgerService;
use Delnavazan\Platform\Core\Application\Finance\OperationalCashReadService;
use Delnavazan\Platform\Core\Application\Finance\OperationalCashRule;

/** Human-first admin surface for the academy's two operational cash balances. */
final class OperationalCashbookController {
    public const MENU_SLUG='dzn-finance-cashbook';
    public static function register():void{
        add_action('admin_menu',array(__CLASS__,'menu'));
        foreach(array('record','convert','reconcile','reverse','reverse_transfer') as$operation)add_action('admin_post_dzn_cashbook_'.$operation,array(__CLASS__,'handle'));
    }
    public static function menu():void{add_submenu_page(Menu::ROOT_SLUG,'Academy account balances','Academy account balances',OperationalCashLedgerService::VIEW_CAPABILITY,self::MENU_SLUG,array(__CLASS__,'screen'));}
    public static function handle():never{
        if(!current_user_can(OperationalCashLedgerService::MANAGE_CAPABILITY))wp_die('You are not allowed to manage academy account balances.');
        $operation=sanitize_key(wp_unslash($_POST['cashbook_operation']??''));if(!in_array($operation,array('record','convert','reconcile','reverse','reverse_transfer'),true))wp_die('Unsupported cashbook action.');
        check_admin_referer('cashbook_'.$operation);
        $input=array();foreach(array('account_key','transaction_kind','amount','transaction_date','description','category','amount_aud','amount_tom','rate_tom_per_aud','as_of_date','statement_balance','evidence_channel','evidence_reference','transaction_id','transfer_id','reason_code','adjustment_direction') as$key){if(isset($_POST[$key])&&is_scalar($_POST[$key]))$input[$key]=sanitize_text_field(wp_unslash((string)$_POST[$key]));}
        $commandKey=isset($_POST['command_key'])&&is_scalar($_POST['command_key'])?sanitize_text_field(wp_unslash((string)$_POST['command_key'])):'';
        try{$service=new OperationalCashLedgerService();$result=match($operation){'record'=>$service->record($input,$commandKey),'convert'=>$service->convertToIran($input,$commandKey),'reconcile'=>$service->reconcile((string)($input['account_key']??''),$input,$commandKey),'reverse'=>$service->reverse((int)($input['transaction_id']??0),(string)($input['reason_code']??''),$commandKey),'reverse_transfer'=>$service->reverseTransfer((int)($input['transfer_id']??0),(string)($input['reason_code']??''),$commandKey)};$status=($result['idempotent']??false)?'already-recorded':'recorded';}
        catch(\InvalidArgumentException $error){$status='invalid';$message=$error->getMessage();}
        catch(\Throwable){$status='not-recorded';$message='The entry was not recorded. Check the account history and try again with a new command.';}
        $account=in_array(($input['account_key']??''),array('australia','iran'),true)?$input['account_key']:'australia';
        $url=add_query_arg(array('page'=>'dzn-finance','tab'=>'ledger','cashbook_account'=>$account,'cashbook_result'=>$status),admin_url('admin.php'));if(isset($message))$url=add_query_arg('cashbook_message',rawurlencode($message),$url);
        wp_safe_redirect($url);exit;
    }
    public static function screen():void{
        if(!current_user_can(OperationalCashLedgerService::VIEW_CAPABILITY))return;
        $accountKey=isset($_GET['account'])&&is_scalar($_GET['account'])?sanitize_key(wp_unslash((string)$_GET['account'])):'australia';if(!in_array($accountKey,array('australia','iran'),true))$accountKey='australia';
        [$from,$through,$month]=self::period();$page=max(1,absint($_GET['cashbook_page']??1));
        try{$read=new OperationalCashReadService();$summary=$read->accountSummaries();$data=$read->dashboard($accountKey,$from,$through,$page);}
        catch(\Throwable){echo '<div class="wrap"><h1>Academy account balances</h1><div class="notice notice-error"><p>The cashbook could not be read. No entry was changed.</p></div></div>';return;}
        echo '<div class="wrap"><h1>Academy account balances</h1><p>Operational bookkeeping for money held in Australia and Iran. Balances stay in their account currency. This screen does not record or reconcile Stripe payments, teacher payability, or formal tax reports.</p>';
        self::notice();echo '<div class="dzn-cashbook-balances">';foreach($summary as$item){$active=$item['key']===$accountKey;$url=add_query_arg(array('page'=>self::MENU_SLUG,'account'=>$item['key'],'month'=>$month),admin_url('admin.php'));echo '<div class="postbox" style="display:inline-block;min-width:220px;margin:0 12px 12px 0;padding:14px"><h2><a href="'.esc_url($url).'">'.esc_html($item['meta']['label']).'</a></h2><p style="font-size:1.5em;margin:8px 0"><strong>'.esc_html(OperationalCashRule::format((int)$item['balance_minor'],$item['meta']['currency'])).'</strong></p>'.($active?'<p>Selected account</p>':'').'</div>'; }echo '</div>';
        echo '<h2>'.esc_html($data['meta']['label']).' · '.esc_html($data['meta']['currency_label']).'</h2>';
        self::periodFilter($month,$accountKey);
        self::periodSummary($data);
        if(current_user_can(OperationalCashLedgerService::MANAGE_CAPABILITY)){self::recordForm($accountKey,$data);if($accountKey==='australia')self::transferForm();self::reconciliationForm($accountKey,$data);}
        self::transactions($data,$accountKey,$month);
        self::reconciliations($data);
        echo '<p class="description">Entries are append-only. Correct a mistaken income or expense by recording a reversal and then entering the corrected fact. Conversions preserve both account amounts, the rate entered at the time, and its evidence reference. Reports keep AUD and TOM totals separate.</p></div>';
    }
    private static function notice():void{
        $state=isset($_GET['cashbook_result'])&&is_scalar($_GET['cashbook_result'])?sanitize_key(wp_unslash((string)$_GET['cashbook_result'])):'';$message=isset($_GET['cashbook_message'])&&is_scalar($_GET['cashbook_message'])?sanitize_text_field(wp_unslash((string)$_GET['cashbook_message'])):'';
        $copy=array('recorded'=>array('success','Entry recorded.'),'already-recorded'=>array('success','This exact entry was already recorded.'),'invalid'=>array('error',$message?:'Check the highlighted entry details and try again.'),'not-recorded'=>array('error',$message?:'The entry was not recorded. Review account history before retrying.'));
        if(isset($copy[$state]))echo '<div class="notice notice-'.esc_attr($copy[$state][0]).'"><p>'.esc_html($copy[$state][1]).'</p></div>';
    }
    private static function period():array{
        $month=isset($_GET['month'])&&is_scalar($_GET['month'])?sanitize_text_field(wp_unslash((string)$_GET['month'])):gmdate('Y-m');
        if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$month)||$month>gmdate('Y-m'))$month=gmdate('Y-m');
        $start=\DateTimeImmutable::createFromFormat('!Y-m-d',$month.'-01',new \DateTimeZone('UTC'));return array($start->format('Y-m-d'),$start->modify('last day of this month')->format('Y-m-d'),$month);
    }
    private static function periodFilter(string $month,string $account):void{echo '<form method="get"><input type="hidden" name="page" value="'.esc_attr(self::MENU_SLUG).'"><input type="hidden" name="account" value="'.esc_attr($account).'"><label for="dzn-cashbook-month">Activity month </label><input id="dzn-cashbook-month" type="month" name="month" value="'.esc_attr($month).'" max="'.esc_attr(gmdate('Y-m')).'"><button class="button">View month</button></form>';}
    private static function periodSummary(array $data):void{
        $income=0;$expense=0;$groups=array();foreach($data['period_totals'] as$row){$i=(int)$row->income_minor;$e=(int)$row->expense_minor;$income+=$i;$expense+=$e;$key=($row->effective_kind==='income'?'Income':'Expense').' · '.($row->effective_category?:'Uncategorised');$groups[$key]=($groups[$key]??0)+($row->effective_kind==='income'?$i:$e);}
        echo '<h3>Income and spending · '.esc_html($data['period_from']).' to '.esc_html($data['period_through']).'</h3><p><strong>Income:</strong> '.esc_html(OperationalCashRule::format($income,$data['meta']['currency'])).' &nbsp; <strong>Spent:</strong> '.esc_html(OperationalCashRule::format($expense,$data['meta']['currency'])).' &nbsp; <strong>Net:</strong> '.esc_html(OperationalCashRule::format($income-$expense,$data['meta']['currency'])).'</p>';
        if($groups){echo '<table class="widefat striped" style="max-width:700px"><thead><tr><th>Category</th><th>Net recorded</th></tr></thead><tbody>';foreach($groups as$label=>$amount)echo '<tr><td>'.esc_html($label).'</td><td>'.esc_html(OperationalCashRule::format($amount,$data['meta']['currency'])).'</td></tr>';echo '</tbody></table>';}
    }
    private static function recordForm(string $account,array $data):void{
        $opening=(new OperationalCashReadService())->hasOpeningBalance($account);
        echo '<details class="postbox" open style="padding:14px"><summary><strong>Record money received or spent</strong></summary><p>Amounts are entered in '.esc_html($data['meta']['currency_label']).' for this account. Each entry keeps its original value.</p>';
        self::formOpen('record');echo '<input type="hidden" name="account_key" value="'.esc_attr($account).'"><table class="form-table"><tbody><tr><th><label for="cashbook-kind">Entry type</label></th><td><select id="cashbook-kind" name="transaction_kind"><option value="income">Money received</option><option value="expense">Money spent</option>'.(!$opening?'<option value="opening_balance">Opening balance</option>':'').'<option value="balance_adjustment">Balance adjustment</option></select></td></tr>';
        echo '<tr><th><label for="cashbook-date">Date</label></th><td><input id="cashbook-date" required type="date" max="'.esc_attr(gmdate('Y-m-d')).'" name="transaction_date" value="'.esc_attr(gmdate('Y-m-d')).'"></td></tr><tr><th><label for="cashbook-amount">Amount ('.esc_html($data['meta']['currency']).')</label></th><td><input id="cashbook-amount" required inputmode="decimal" name="amount" placeholder="'.($data['meta']['currency']==='AUD'?'0.00':'0').'">'.($data['meta']['currency']==='AUD'?'<p class="description">Dollars and cents, for example 125.50.</p>':'<p class="description">Whole tomans. Persian and Arabic numerals are accepted.</p>').'</td></tr><tr><th><label for="cashbook-category">Category</label></th><td><input id="cashbook-category" name="category" maxlength="100" placeholder="For example: lessons, books, postage"></td></tr><tr><th><label for="cashbook-description">Description</label></th><td><input id="cashbook-description" class="large-text" required maxlength="500" name="description"></td></tr>';
        echo '<tr><th><label for="cashbook-direction">Adjustment direction</label></th><td><select id="cashbook-direction" name="adjustment_direction"><option value="increase">Increase balance</option><option value="decrease">Decrease balance</option></select> <label for="cashbook-record-reason">Reason</label> <select id="cashbook-record-reason" name="reason_code"><option value="data_entry_correction">Data entry correction</option><option value="opening_balance">Opening balance correction</option><option value="balance_reconciliation">Statement review</option><option value="other_reviewed_correction">Other reviewed correction</option></select><p class="description">Used only for a balance adjustment. Adjustments are excluded from earned and spent reports.</p></td></tr>';
        self::evidenceFields(true);echo '</tbody></table>';submit_button('Record entry');echo '</form></details>';
    }
    private static function transferForm():void{
        echo '<details class="postbox" style="padding:14px"><summary><strong>Convert Australian dollars and record the Iran transfer</strong></summary><p>This records one linked outflow in Australia and inflow in Iran. Enter the actual amounts and the historical quote; the system never fetches or reapplies a current rate. Record transfer fees separately as an expense.</p>';
        self::formOpen('convert');echo '<table class="form-table"><tbody><tr><th><label for="cashbook-aud">Australian dollars sent</label></th><td><input id="cashbook-aud" required inputmode="decimal" name="amount_aud" placeholder="1,500.00"></td></tr><tr><th><label for="cashbook-tom">Tomans received in Iran</label></th><td><input id="cashbook-tom" required inputmode="numeric" name="amount_tom" placeholder="98,000,000"></td></tr><tr><th><label for="cashbook-rate">Recorded rate (TOM per AUD)</label></th><td><input id="cashbook-rate" required inputmode="decimal" name="rate_tom_per_aud" placeholder="65,333.33333333"></td></tr><tr><th><label for="cashbook-transfer-date">Transfer date</label></th><td><input id="cashbook-transfer-date" required type="date" max="'.esc_attr(gmdate('Y-m-d')).'" name="transaction_date" value="'.esc_attr(gmdate('Y-m-d')).'"></td></tr><tr><th><label for="cashbook-transfer-description">Description</label></th><td><input id="cashbook-transfer-description" class="large-text" required maxlength="500" name="description"></td></tr><tr><th colspan="2"><p class="description">The rate and amounts are saved as entered for this conversion.</p></th></tr>';
        self::evidenceFields(true);echo '</tbody></table>';submit_button('Record linked conversion');echo '</form></details>';
    }
    private static function reconciliationForm(string $account,array $data):void{
        echo '<details class="postbox" style="padding:14px"><summary><strong>Compare an account statement</strong></summary><p>Record the external statement balance and its date. This creates a read-only reconciliation result; it does not change the ledger.</p>';
        self::formOpen('reconcile');echo '<input type="hidden" name="account_key" value="'.esc_attr($account).'"><table class="form-table"><tbody><tr><th><label for="cashbook-as-of">Statement date</label></th><td><input id="cashbook-as-of" required type="date" max="'.esc_attr(gmdate('Y-m-d')).'" name="as_of_date" value="'.esc_attr(gmdate('Y-m-d')).'"></td></tr><tr><th><label for="cashbook-statement-balance">Statement balance ('.esc_html($data['meta']['currency']).')</label></th><td><input id="cashbook-statement-balance" required inputmode="decimal" name="statement_balance"></td></tr>';self::evidenceFields(true);echo '</tbody></table>';submit_button('Compare balances');echo '</form></details>';
    }
    private static function transactions(array $data,string $account,string $month):void{
        echo '<h3>Account activity · '.esc_html((string)$data['transaction_count']).' entries this month</h3>';
        if(!$data['transactions']){echo '<p>No entries for this month yet.</p>';return;}
        $reasons=array('data_entry_correction'=>'Data entry correction','opening_balance'=>'Opening balance','balance_reconciliation'=>'Statement review','other_reviewed_correction'=>'Other reviewed correction');
        echo '<table class="widefat striped"><thead><tr><th>Date</th><th>Entry</th><th>Category</th><th>Description</th><th>Amount</th><th>Evidence / action</th></tr></thead><tbody>';
        foreach($data['transactions'] as$row){$label=array('income'=>'Money received','expense'=>'Money spent','opening_balance'=>'Opening balance','balance_adjustment'=>'Balance adjustment','transfer_in'=>'Transfer received','transfer_out'=>'Transfer sent','reversal'=>'Reversal')[$row->transaction_kind]??'Entry';$signed=(int)$row->direction>0?'+':'−';$description=(string)$row->description;if($row->rate_tom_per_aud!==null)$description.=' · 1 AUD = '.(string)$row->rate_tom_per_aud.' TOM (historical rate)';echo '<tr><td>'.esc_html((string)$row->transaction_date).'</td><td>'.esc_html($label).'</td><td>'.esc_html((string)($row->category?:'—')).'</td><td>'.esc_html($description).'</td><td>'.esc_html($signed.OperationalCashRule::format((int)$row->amount_minor,(string)$row->currency)).'</td><td>'.($row->evidence_reference!==null?'<span title="Evidence reference">'.esc_html((string)$row->evidence_reference).'</span>':'—');
            if(current_user_can(OperationalCashLedgerService::MANAGE_CAPABILITY)&&$row->transfer_id===null&&$row->transaction_kind!=='reversal'&&$row->transaction_kind!=='transfer_in'&&$row->transaction_kind!=='transfer_out'){self::reverseForm((int)$row->id,$reasons);}
            if(current_user_can(OperationalCashLedgerService::MANAGE_CAPABILITY)&&$row->transfer_id!==null&&$row->transaction_kind!=='reversal')self::reverseTransferForm((int)$row->transfer_id,$reasons);
            echo '</td></tr>';}
        echo '</tbody></table>';
        if($data['pages']>1){$base=array('page'=>self::MENU_SLUG,'account'=>$account,'month'=>$month);echo '<p class="tablenav">Page '.esc_html((string)$data['page']).' of '.esc_html((string)$data['pages']).' ';if($data['page']>1)echo '<a class="button" href="'.esc_url(add_query_arg($base+array('cashbook_page'=>$data['page']-1),admin_url('admin.php'))).'">Previous</a> ';if($data['page']<$data['pages'])echo '<a class="button" href="'.esc_url(add_query_arg($base+array('cashbook_page'=>$data['page']+1),admin_url('admin.php'))).'">Next</a>';echo '</p>';}
    }
    private static function reconciliations(array $data):void{
        echo '<h3>Recent statement comparisons</h3>';if(!$data['reconciliations']){echo '<p>No statement comparisons recorded yet.</p>';return;}
        echo '<table class="widefat striped"><thead><tr><th>As of</th><th>Ledger balance</th><th>Statement balance</th><th>Difference (ledger minus statement)</th><th>Evidence reference</th></tr></thead><tbody>';foreach($data['reconciliations'] as$row){$diff=(int)$row->difference_minor;$sign=$diff>0?'+':($diff<0?'−':'');echo '<tr><td>'.esc_html((string)$row->as_of_date).'</td><td>'.esc_html(OperationalCashRule::format((int)$row->system_balance_minor,$data['meta']['currency'])).'</td><td>'.esc_html(OperationalCashRule::format((int)$row->statement_balance_minor,$data['meta']['currency'])).'</td><td>'.esc_html($sign.OperationalCashRule::format(abs($diff),$data['meta']['currency'])).'</td><td>'.($row->evidence_reference!==null?esc_html((string)$row->evidence_reference):'—').'</td></tr>'; }echo '</tbody></table>';
    }
    private static function reverseForm(int $id,array $reasons):void{echo '<details><summary>Correct by reversal</summary>';self::formOpen('reverse');echo '<input type="hidden" name="transaction_id" value="'.esc_attr((string)$id).'"><label class="screen-reader-text" for="cashbook-reason-'.$id.'">Correction reason</label><select id="cashbook-reason-'.$id.'" name="reason_code">';foreach($reasons as$key=>$label)echo '<option value="'.esc_attr($key).'">'.esc_html($label).'</option>';echo '</select> ';submit_button('Reverse entry','secondary','submit',false);echo '</form></details>';}
    private static function reverseTransferForm(int $id,array $reasons):void{echo '<details><summary>Correct paired transfer</summary>';self::formOpen('reverse_transfer');echo '<input type="hidden" name="transfer_id" value="'.esc_attr((string)$id).'"><label class="screen-reader-text" for="cashbook-transfer-reason-'.$id.'">Correction reason</label><select id="cashbook-transfer-reason-'.$id.'" name="reason_code">';foreach($reasons as$key=>$label)echo '<option value="'.esc_attr($key).'">'.esc_html($label).'</option>';echo '</select> ';submit_button('Reverse both sides','secondary','submit',false);echo '</form></details>';}
    private static function formOpen(string $operation):void{echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dzn_cashbook_'.esc_attr($operation).'"><input type="hidden" name="cashbook_operation" value="'.esc_attr($operation).'"><input type="hidden" name="command_key" value="'.esc_attr(wp_generate_uuid4()).'">';wp_nonce_field('cashbook_'.$operation);}
    private static function evidenceFields(bool $required):void{echo '<tr><th><label for="cashbook-evidence">Evidence reference'.($required?' <span class="required">*</span>':'').'</label></th><td><input id="cashbook-evidence" class="large-text" maxlength="191" name="evidence_reference" '.($required?'required':'').' placeholder="Statement, receipt or exchange reference"><label for="cashbook-evidence-channel">Evidence type</label> <select id="cashbook-evidence-channel" name="evidence_channel"><option value="staff_record">Staff record</option><option value="document_reference">Document or statement</option></select><p class="description">Keep supporting documents in your records. The reference label is retained with a one-way digest.</p></td></tr>';}
}
